<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class Quote extends Model { protected $fillable = ['business_id','enquiry_id','customer_id','number','status','currency','subtotal','tax_rate','tax_total','total','notes','terms','expires_at','approved_at','sent_at','responded_at','public_token','public_token_expires_at','version']; protected function casts(): array { return ['subtotal'=>'decimal:2','tax_rate'=>'decimal:4','tax_total'=>'decimal:2','total'=>'decimal:2','expires_at'=>'datetime','approved_at'=>'datetime','sent_at'=>'datetime','responded_at'=>'datetime','public_token_expires_at'=>'datetime']; } public function business() { return $this->belongsTo(Business::class); } public function customer() { return $this->belongsTo(Customer::class); } public function enquiry() { return $this->belongsTo(Enquiry::class); } public function items() { return $this->hasMany(QuoteItem::class)->orderBy('sort_order'); } public function events() { return $this->hasMany(QuoteEvent::class); } public function booking() { return $this->hasOne(Booking::class); } public function isPubliclyViewable(): bool { return $this->public_token_expires_at?->isFuture() && in_array($this->status, ['sent','accepted','declined'], true); } }
